    if (ns.fileExists('FTPCrack.exe', 'home')) { ns.ftpcrack(host); portsOpened++; }
    if (ns.fileExists('relaySMTP.exe', 'home')) { ns.relaysmtp(host); portsOpened++; }
    if (ns.fileExists('HTTPWorm.exe', 'home')) { ns.httpworm(host); portsOpened++; }
    if (ns.fileExists('SQLInject.exe', 'home')) { ns.sqlinject(host); portsOpened++; }

    if (portsOpened >= portsRequired) ns.nuke(host);
  }

  // Main loop
  const playerLevel = ns.getHackingLevel();
  while (true) {
    let target = null;
    let maxMoney = 0;

    for (const host of servers) {
      if (!ns.hasRootAccess(host)) continue;
      const reqLevel = ns.getServerRequiredHackingLevel(host);
      if (reqLevel > playerLevel) continue;
      const max = ns.getServerMaxMoney(host);
      if (max > maxMoney) {
        maxMoney = max;
        target = host;
      }
    }

    if (!target) {
      await ns.sleep(1000);
      continue;
    }

    const security = ns.getServerSecurityLevel(target);
    const minSecurity = ns.getServerMinSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);
    const maxMoney2 = ns.getServerMaxMoney(target);

    if (security > minSecurity + 5) {
      await ns.weaken(target);
    } else if (money < maxMoney2 * 0.8) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

